    score += 0.20 * mean_gap / capacity;

    // Scarcity of feasible bins is a stronger signal than raw bin count.
    let scarcity = if fitting > 0.0 {
        (1.0 / fitting).min(1.0)
    } else {
        1.0
    };
    score += 3.0 * scarcity * (post / capacity);

    // If many bins can accept the item, avoid wasting an almost-perfect bin.
    if fitting >= 2.0 {
        let compactness = (post / capacity).max(0.0);
        score += 0.8 * compactness;
    }

    // A new bin is attractive when the current item is large relative to the
    // average residual, or when the available placements are unusually poor.
    let item_vs_mean = if mean > 0.0 {
        item_size as f64 / mean
    } else {
        1.0
    };
    score -= 0.9 * (item_vs_mean - 1.0).max(0.0);

    let pressure = (open_bins / (open_bins + 8.0)).min(1.0);
    score += 1.5 * pressure * (post / capacity);

    // Reward a bin that can immediately accept the next item.
    if next_size > 0.0 && post >= next_size {
        score -= 1.8 * next_size / capacity;
    }

    // Late in the stream, small residual fragments become increasingly costly.
    score += 1.8 * progress * (post / capacity);

    // Keep a mild preference for tighter residuals overall.
    score += 0.35 * post / capacity;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

    // Dead space is especially costly when it cannot accommodate the known next item.
    let lookahead_penalty = if next_item_size == 0 {
        0.0
    } else if post_residual < next_item_size {
        (next_item_size - post_residual) as f64
    } else {
        0.0
    };
    score += 1.35 * lookahead_penalty;

    // Favor residuals close to the mean residual of currently open bins.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.20 * mean_gap;

    // Strongly discourage fragmented residual space that leaves many unusable bins.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 2.0 * (item_size - post_residual.min(item_size)) as f64;
    }

    // If this is the only fitting bin, preserve its capacity for a better future item.
    if fitting_bins_count == 1 {
        score += 0.75 * post_residual as f64;
    }

    // Near the end of the stream, maximize immediate consolidation.
    score -= 0.65 * progress * post_residual as f64;

    // Opening an empty bin is preferred only when all alternatives would create
    // substantially worse dead space or no existing bin can fit the item.
    if bin_residual == bin_capacity {
        score += 18.0;
        if open_bins_count > 0 {
            score -= 4.0 * (open_bins_count as f64).sqrt();
        }
    }

    score
}
